// Types of the tenbri package (tenbri.js). The native addon's own types are generated by napi-rs
// into index.d.ts.

/** An entry as stored (format v1, spec/format-v1.md). */
export interface Entry {
  v: number
  id: string
  stream: string
  seq: number
  ts: string
  kind: 'decision' | 'approval' | 'key' | 'reconcile' | 'note'
  phase?: 'intent' | 'outcome'
  intent?: string
  status?: Status
  source?: 'sdk' | 'proxy' | 'ingest'
  durability?: 'local' | 'replicated' | 'postgres'
  principal?: { kind: PrincipalKind; id: string }
  action?: { type: string; target?: string }
  subject?: string
  inputs?: Input[]
  rule?: { ref: string; version: string; result: string }
  prev?: string
  signer: string
  sig: string
  [member: string]: unknown
}

/** A draft entry: what the writer does not fill in (`v`, `stream`, `seq`, `prev`, `signer`, `sig`).
 * Give it an `id` (`newId()`) to make retries idempotent. */
export type Draft = Omit<Partial<Entry>, 'principal'> & { principal?: Principal }

export type Status = 'ok' | 'error' | 'refused' | 'unknown'
export type PrincipalKind = 'agent' | 'person' | 'service'
/** `{ kind, id }`, `'agent:support'`, or `'support'` (an agent). */
export type Principal = string | { kind: PrincipalKind; id: string }
export interface Input {
  ref: string
  version: string
  digest: string
}

export interface OpenOptions {
  /** The keys directory; default `$TENBRI_KEYS`, else `~/.config/tenbri/keys`. Never inside the
   * stream. Without the stream's keys there, the stream opens read-only. */
  keys?: string
  /** The genesis key to pin: `sha256:…` fingerprint or `ed25519:…` public key. */
  key?: string
  /** Create the stream and its keys if there is none. */
  create?: boolean
  /** Keys the digests of inputs a run reads (HMAC-SHA256). */
  digestKey?: string | Uint8Array
}

export interface DecisionOptions extends Omit<Draft, 'action'> {
  action: string
  target?: string
}

export interface VerifyReport {
  /** Verified: nothing broken, against a pinned key. */
  ok: boolean
  stream: string | null
  /** Entries checked before the first break, or all of them. */
  entries: number
  /** The fingerprint checked against; null when unpinned, which proves nothing about the writer. */
  pinnedKey: string | null
  broken: { seq: number; code: string; message: string } | null
  /** The size of the latest checkpoint, which the stream matched, if it has one. */
  checkpoint: number | null
}

export interface QueryFilter {
  action?: string
  target?: string
  principal?: Principal
  subject?: string
  /** `'ref@version'` strings or `[ref, version]` pairs; all must be among the entry's inputs. */
  inputs?: Array<string | [string, string]>
  afterSeq?: number
  limit?: number
}

export interface Match {
  /** `verified`, `unpinned` (no key pinned at open) or `broken`. */
  verification: 'verified' | 'unpinned' | 'broken'
  entry: Entry
}

export declare class Tenbri {
  /** Opens the stream at `url`: a directory, `file://…`, `s3://bucket/prefix` or `r2://bucket/prefix`
   * (credentials from `AWS_*`; `CLOUDFLARE_ACCOUNT_ID` for R2). */
  static open(url: string | URL, options?: OpenOptions): Promise<Tenbri>
  /** The stream id, `tnb1:…`. */
  readonly id: string
  /** The genesis key's fingerprint: what a verifier pins. */
  readonly fingerprint: string | null
  /** Whether this machine holds the keys to write the stream. */
  readonly writable: boolean
  digest(content: string | Uint8Array): string
  append(entry: Draft): Promise<Entry>
  /** Records an intent, durable before the action runs. */
  intent(draft: Draft): Promise<Entry>
  /** Records the outcome of `intent` (the entry, or its id). */
  outcome(intent: Entry | string, status?: Status, fields?: Draft): Promise<Entry>
  /** Records a decision around `fn`: intent before, outcome after (`ok`, `refused`, `error`). */
  decision<T>(options: DecisionOptions, fn: (intent: Entry) => T | Promise<T>): Promise<T>
  run<T>(options: { principal: Principal }, fn: (run: Run) => T | Promise<T>): Promise<T>
  verify(key?: string): Promise<VerifyReport>
  query(filter?: QueryFilter): Promise<Match[]>
  flush(): Promise<void>
  close(): Promise<void>
}

export declare class Run {
  readonly principal: { kind: PrincipalKind; id: string }
  /** Records a read: the next decision lists it among its inputs, with its keyed digest. */
  read(ref: string, read: { version: string; content?: string | Uint8Array; digest?: string }): void
  decision<T>(options: DecisionOptions, fn: (intent: Entry) => T | Promise<T>): Promise<T>
}

/** Throw inside a decision when your own policy refuses the action: recorded as `refused`. */
export declare class Refused extends Error {}

/** A Tenbri failure, with its stable TENBRI_* code, shared with tenbrid. */
export declare class TenbriError extends Error {
  readonly code: string
  /** The format v1 error code (`bad_signature`, …), where there is one. */
  readonly reason?: string
  /** The id of the entry being written: retry with it. */
  readonly id?: string
}
export declare class InvalidRequestError extends TenbriError {}
export declare class InvalidEntryError extends TenbriError {}
export declare class NotFoundError extends TenbriError {}
export declare class IdempotencyConflictError extends TenbriError {}
export declare class WriteConflictError extends TenbriError {}
export declare class DeadlineExceededError extends TenbriError {}
export declare class StoreUnavailableError extends TenbriError {}
export declare class NoSessionKeyError extends TenbriError {}
export declare class StreamBrokenError extends TenbriError {}

/** A new entry id (ULID), for idempotent retries. */
export declare function newId(): string
export declare const version: string
